def transform(grid):
    h, w = len(grid), len(grid[0])

    # Identify separator rows and columns, then the enclosed panels.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != 0]
    sep_cols = [c for c in range(w) if all(grid[r][c] == grid[0][c] for r in range(h))
                and len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != 0]

    # In these puzzles the separator color is constant; only full separator
    # lines are relevant.
    sep_color = grid[0][sep_cols[0]] if sep_cols else None
    sep_rows = [r for r in range(h) if all(v == sep_color for v in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[r][c] == sep_color for r in range(h))]

    row_bounds = []
    start = 0
    for r in sep_rows:
        if start < r:
            row_bounds.append((start, r))
        start = r + 1
    if start < h:
        row_bounds.append((start, h))

    col_bounds = []
    start = 0
    for c in sep_cols:
        if start < c:
            col_bounds.append((start, c))
        start = c + 1
    if start < w:
        col_bounds.append((start, w))

    # The motif is the nonempty panel outside the first column with the
    # greatest number of colored cells.
    motif = None
    best = -1
    for ri, (r0, r1) in enumerate(row_bounds):
        for ci, (c0, c1) in enumerate(col_bounds):
            if ci == 0:
                continue
            cells = [(r-r0, c-c0) for r in range(r0, r1)
                     for c in range(c0, c1) if grid[r][c] != 0 and grid[r][c] != sep_color]
            # The motif may use the separator color itself (as in the demo).
            if not cells:
                cells = [(r-r0, c-c0) for r in range(r0, r1)
                         for c in range(c0, c1) if grid[r][c] != 0]
            if len(cells) > best:
                best, motif = len(cells), cells

    out = [[sep_color if (r in sep_rows or c in sep_cols) else 0 for c in range(w)]
           for r in range(h)]

    for r0, r1 in row_bounds:
        c0, c1 = col_bounds[0]
        color = next((grid[r][c] for r in range(r0, r1) for c in range(c0, c1)
                      if grid[r][c] != 0), 0)
        for a, b in col_bounds:
            for dr, dc in motif:
                if r0 + dr < r1 and a + dc < b:
                    out[r0 + dr][a + dc] = color

    return out
